Instrução: Implementar o corpo completo de todos os métodos PHP e todo o JavaScript. Seguir a ordem abaixo. Não alterar assinaturas. Não criar arquivos novos.

=== 1. includes/class-activator.php ===

activate():
  self::create_tables();
  self::register_wc_product();

create_tables():
  global $wpdb;
  $charset = $wpdb->get_charset_collate();
  $t1 = $wpdb->prefix . CC_PACKS_TABLE;
  $t2 = $wpdb->prefix . CC_PACKS_SESSIONS_TABLE;
  $sql1 = "CREATE TABLE IF NOT EXISTS {$t1} (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    price DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    dme_ids JSON NOT NULL,
    adm_id INT UNSIGNED NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_adm (adm_id)
  ) {$charset};";
  $sql2 = "CREATE TABLE IF NOT EXISTS {$t2} (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    token VARCHAR(64) NOT NULL,
    user_id INT UNSIGNED NOT NULL,
    composition JSON NOT NULL,
    total DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY idx_token (token),
    KEY idx_user (user_id),
    KEY idx_status (status)
  ) {$charset};";
  require_once ABSPATH . 'wp-admin/includes/upgrade.php';
  dbDelta($sql1);
  dbDelta($sql2);

register_wc_product():
  $product_id = get_option(CC_PACKS_PRODUCT_OPTION, 0);
  if ($product_id && get_post_status($product_id) === 'publish') return;
  $product = new WC_Product_Simple();
  $product->set_name('Packs');
  $product->set_status('publish');
  $product->set_catalog_visibility('hidden');
  $product->set_price(1);
  $product->set_regular_price(1);
  $product->set_virtual(true);
  $product->set_sold_individually(false);
  $id = $product->save();
  update_option(CC_PACKS_PRODUCT_OPTION, $id);

=== 2. includes/class-crud.php ===

create(array $data):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_TABLE;
  $result = $wpdb->insert($table, [
    'name'    => sanitize_text_field($data['name'] ?? ''),
    'price'   => floatval($data['price'] ?? 0),
    'dme_ids' => wp_json_encode($data['dme_ids'] ?? []),
    'adm_id'  => intval($data['adm_id'] ?? get_current_user_id()),
  ], ['%s','%f','%s','%d']);
  return $result ? $wpdb->insert_id : false;

update(int $id, array $data):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_TABLE;
  $fields = [];
  $formats = [];
  if (isset($data['name']))    { $fields['name']    = sanitize_text_field($data['name']); $formats[] = '%s'; }
  if (isset($data['price']))   { $fields['price']   = floatval($data['price']);             $formats[] = '%f'; }
  if (isset($data['dme_ids'])) { $fields['dme_ids'] = wp_json_encode($data['dme_ids']);    $formats[] = '%s'; }
  if (empty($fields)) return false;
  return $wpdb->update($table, $fields, ['id' => $id], $formats, ['%d']) !== false;

delete(int $id):
  global $wpdb;
  return $wpdb->delete($wpdb->prefix . CC_PACKS_TABLE, ['id' => $id], ['%d']) !== false;

get(int $id):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_TABLE;
  $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $id), ARRAY_A);
  if (!$row) return null;
  $row['dme_ids'] = json_decode($row['dme_ids'], true) ?: [];
  return $row;

get_all():
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_TABLE;
  $rows = $wpdb->get_results("SELECT * FROM {$table} ORDER BY created_at DESC", ARRAY_A) ?: [];
  return array_map(function($r){ $r['dme_ids'] = json_decode($r['dme_ids'], true) ?: []; return $r; }, $rows);

get_by_adm(int $adm_id):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_TABLE;
  $rows = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE adm_id = %d ORDER BY created_at DESC", $adm_id), ARRAY_A) ?: [];
  return array_map(function($r){ $r['dme_ids'] = json_decode($r['dme_ids'], true) ?: []; return $r; }, $rows);

=== 3. includes/class-session.php ===

generate_token():
  return bin2hex(random_bytes(16));

calculate_total(array $composition):
  // composition shape: { pack_id: qty }
  $total = 0.0;
  foreach ($composition as $pack_id => $qty) {
    $pack = CC_Packs_CRUD::get(intval($pack_id));
    if ($pack) $total += floatval($pack['price']) * intval($qty);
  }
  return $total;

create(int $user_id, array $composition):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_SESSIONS_TABLE;
  $token = self::generate_token();
  $total = self::calculate_total($composition);
  $result = $wpdb->insert($table, [
    'token'       => $token,
    'user_id'     => $user_id,
    'composition' => wp_json_encode($composition),
    'total'       => $total,
    'status'      => CC_PACKS_STATUS_PENDING,
  ], ['%s','%d','%s','%f','%s']);
  return $result ? $token : false;

get_by_token(string $token):
  global $wpdb;
  $table = $wpdb->prefix . CC_PACKS_SESSIONS_TABLE;
  $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE token = %s", $token), ARRAY_A);
  if (!$row) return null;
  $row['composition'] = json_decode($row['composition'], true) ?: [];
  return $row;

update_status(int $id, string $status):
  global $wpdb;
  $allowed = [CC_PACKS_STATUS_PENDING, CC_PACKS_STATUS_APPROVED, CC_PACKS_STATUS_REJECTED];
  if (!in_array($status, $allowed, true)) return false;
  return $wpdb->update(
    $wpdb->prefix . CC_PACKS_SESSIONS_TABLE,
    ['status' => $status], ['id' => $id], ['%s'], ['%d']
  ) !== false;

get_by_adm(int $adm_id):
  // retorna sessions onde pelo menos 1 pack da composition pertence a adm_id
  global $wpdb;
  $st = $wpdb->prefix . CC_PACKS_SESSIONS_TABLE;
  $pt = $wpdb->prefix . CC_PACKS_TABLE;
  $rows = $wpdb->get_results(
    $wpdb->prepare(
      "SELECT DISTINCT s.* FROM {$st} s
       JOIN {$pt} p ON JSON_CONTAINS(s.composition, CAST(p.id AS JSON), '$')
       WHERE p.adm_id = %d
       ORDER BY s.created_at DESC",
      $adm_id
    ), ARRAY_A
  ) ?: [];
  return array_map(function($r){ $r['composition'] = json_decode($r['composition'], true) ?: []; return $r; }, $rows);

=== 4. includes/class-wc-bridge.php ===

get_product_id():
  return intval(get_option(CC_PACKS_PRODUCT_OPTION, 0));

get_or_create_product():
  $id = self::get_product_id();
  if ($id && get_post_status($id) === 'publish') return $id;
  CC_Packs_Activator::register_wc_product();
  return self::get_product_id();

inject_dynamic_price(object $cart):
  if (is_admin() && !defined('DOING_AJAX')) return;
  foreach ($cart->get_cart() as $item) {
    if (!empty($item['cc_pack_price']) && $item['data'] instanceof WC_Product) {
      $item['data']->set_price(floatval($item['cc_pack_price']));
    }
  }

set_cart_item_name(string $name, array $cart_item, string $key):
  return !empty($cart_item['cc_pack_name']) ? esc_html($cart_item['cc_pack_name']) : $name;

set_order_item_meta(object $item, string $key, array $values, object $order):
  if (!empty($values['cc_pack_name']))  $item->set_name($values['cc_pack_name']);
  if (!empty($values['cc_pack_desc']))  $item->add_meta_data('Descrição', $values['cc_pack_desc'], true);
  if (!empty($values['cc_pack_token'])) $item->add_meta_data('Token', $values['cc_pack_token'], true);

=== 5. includes/class-api.php ===

public_permission(): return true;
admin_permission(): return current_user_can('manage_options');

get_packs(object $request):
  $packs = CC_Packs_CRUD::get_all();
  return new WP_REST_Response(['data' => $packs], 200);

create_pack(object $request):
  $body = $request->get_json_params();
  if (empty($body['name']) || !isset($body['price']) || empty($body['dme_ids'])) {
    return new WP_REST_Response(['error' => 'name, price e dme_ids são obrigatórios'], 400);
  }
  $id = CC_Packs_CRUD::create([
    'name'    => $body['name'],
    'price'   => $body['price'],
    'dme_ids' => $body['dme_ids'],
    'adm_id'  => get_current_user_id(),
  ]);
  if (!$id) return new WP_REST_Response(['error' => 'Erro ao criar pack'], 500);
  return new WP_REST_Response(['id' => $id], 201);

update_pack(object $request):
  $id   = intval($request->get_param('id'));
  $body = $request->get_json_params();
  $ok   = CC_Packs_CRUD::update($id, $body);
  return new WP_REST_Response(['success' => $ok], $ok ? 200 : 500);

delete_pack(object $request):
  $id = intval($request->get_param('id'));
  $ok = CC_Packs_CRUD::delete($id);
  return new WP_REST_Response(['success' => $ok], $ok ? 200 : 500);

create_session(object $request):
  $body = $request->get_json_params();
  if (empty($body['composition']) || !is_array($body['composition'])) {
    return new WP_REST_Response(['error' => 'composition é obrigatório'], 400);
  }
  $user_id = get_current_user_id();
  // normaliza composition: [{pack_id, qty}] → {pack_id: qty}
  $composition = [];
  foreach ($body['composition'] as $item) {
    $pid = intval($item['pack_id'] ?? $item[0] ?? 0);
    $qty = intval($item['qty'] ?? $item[1] ?? 1);
    if ($pid > 0) $composition[$pid] = ($composition[$pid] ?? 0) + $qty;
  }
  $token = CC_Packs_Session::create($user_id, $composition);
  if (!$token) return new WP_REST_Response(['error' => 'Erro ao criar sessão'], 500);
  $redirect = add_query_arg('token', $token, CC_PACKS_FORM_BASE_URL);
  return new WP_REST_Response(['token' => $token, 'redirect' => $redirect], 201);

get_session(object $request):
  $token   = sanitize_text_field($request->get_param('token'));
  $session = CC_Packs_Session::get_by_token($token);
  if (!$session) return new WP_REST_Response(['error' => 'Sessão não encontrada'], 404);
  return new WP_REST_Response(['data' => $session], 200);

update_session_status(object $request):
  $id     = intval($request->get_param('id'));
  $body   = $request->get_json_params();
  $status = sanitize_text_field($body['status'] ?? '');
  $ok     = CC_Packs_Session::update_status($id, $status);
  return new WP_REST_Response(['success' => $ok], $ok ? 200 : 400);

=== 6. admin/class-admin-page.php ===

